{
  "project_id": "68a5c2cde2334b1e9a3e",
  "name": "harden_delete_account_access",
  "query": "create or replace function public.delete_account()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from auth.sessions where user_id = (select auth.uid());
  delete from auth.users where id = (select auth.uid());
$$;

revoke execute on function public.delete_account() from public;
revoke execute on function public.delete_account() from anon;
grant execute on function public.delete_account() to authenticated;

drop policy if exists "users read own profile" on public.profiles;
create policy "users read own active profile" on public.profiles
  for select to authenticated
  using (id = (select auth.uid()) and deleted = false);

drop policy if exists "users write own notes" on public.notes;
create policy "users write own active notes" on public.notes
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.deleted = false
    )
  );

drop policy if exists "users read own notes" on public.notes;
create policy "users read own active notes" on public.notes
  for select to authenticated
  using (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.deleted = false
    )
  );"
}

